-- 0019 part 4 of 4: Vegan nutrition plans. Run the parts in order (part 1 adds the new foods).

-- Vegan: 14 plans, 1,400 to 4,000 kcal.
delete from public.templates where kind = 'nutrition' and name like 'Vegan, %kcal';
insert into public.templates (kind, name, summary, goal, level, audience, competitor, tags, body)
select 'nutrition', v.name, v.summary, v.goal, 'Beginner', 'any', 'any', v.tags::text[], v.body
from (values
('Vegan, 1,400 kcal', '1,400 kcal (5,858 kJ). Tofu, beans, lentils, soya and a plant protein shake. No animal products. Training and rest days, 3 meals and a snack.', 'General health', '{"vegan","trial","1400 kcal"}', $${"style":"plan","notes":"Eat roughly the same each day and don't stress about being exact. Hit your protein first. Training days swap the afternoon snack for a post-workout meal with more carbs. Weigh your food for the first week or two if you can, then hand portions are fine. Fill up on veg as much as you like.","day_types":[{"name":"Training day","weekdays":[1,2,4,5],"kcal":1400,"protein_g":100,"carbs_g":147,"fat_g":39,"fibre_g":34,"sodium_mg":null,"water_ml":null,"palms":4,"fists":4,"cupped":5,"thumbs":4,"notes":"Post-workout meal within an hour or so of training.","meals":[{"name":"Breakfast","notes":"Stir the protein in once the oats are cooked. Swap: soya yoghurt for some of the milk, or wholemeal toast with peanut butter.","items":[{"food":"Oats, rolled","grams":45},{"food":"Soya milk, unsweetened","grams":140},{"food":"Per4m Plant Protein","grams":25},{"food":"Frozen mixed berries","grams":55},{"food":"Chia seeds","grams":5}]},{"name":"Lunch","notes":"Swap: chickpeas or edamame for the lentils; rice or a wrap for the quinoa.","items":[{"food":"Lentils, cooked","grams":85},{"food":"Quinoa, cooked","grams":85},{"food":"Spinach","grams":45},{"food":"Tomato","grams":70},{"food":"Avocado","grams":30},{"food":"Hummus","grams":15}]},{"name":"Post-workout","notes":"Within an hour or so of training. Per4m's Cream of Rice is labelled vegan. Swap: oats or rice cakes for the cream of rice.","items":[{"food":"Per4m Plant Protein","grams":25},{"food":"Cream of rice, dry","grams":20},{"food":"Banana","grams":55}]},{"name":"Dinner","notes":"Swap: tempeh, seitan or a vegan mince for the tofu; noodles or potatoes for the rice.","items":[{"food":"Tofu, firm","grams":170},{"food":"Basmati rice, cooked","grams":110},{"food":"Broccoli","grams":85},{"food":"Edamame beans, frozen","grams":70},{"food":"Soy sauce","grams":15}]}]},{"name":"Rest day","weekdays":[3,6,7],"kcal":1400,"protein_g":90,"carbs_g":137,"fat_g":46,"fibre_g":36,"sodium_mg":null,"water_ml":null,"palms":4,"fists":4,"cupped":5,"thumbs":5,"notes":null,"meals":[{"name":"Breakfast","notes":"Stir the protein in once the oats are cooked. Swap: soya yoghurt for some of the milk, or wholemeal toast with peanut butter.","items":[{"food":"Oats, rolled","grams":45},{"food":"Soya milk, unsweetened","grams":140},{"food":"Per4m Plant Protein","grams":25},{"food":"Frozen mixed berries","grams":55},{"food":"Chia seeds","grams":5}]},{"name":"Lunch","notes":"Swap: chickpeas or edamame for the lentils; rice or a wrap for the quinoa.","items":[{"food":"Lentils, cooked","grams":85},{"food":"Quinoa, cooked","grams":85},{"food":"Spinach","grams":45},{"food":"Tomato","grams":70},{"food":"Avocado","grams":30},{"food":"Hummus","grams":15}]},{"name":"Snack","notes":"Swap: any fruit for the banana, walnuts for the almonds.","items":[{"food":"Soya yoghurt, plain","grams":170},{"food":"Banana","grams":70},{"food":"Almonds","grams":10}]},{"name":"Dinner","notes":"Swap: tempeh, seitan or a vegan mince for the tofu; noodles or potatoes for the rice.","items":[{"food":"Tofu, firm","grams":170},{"food":"Basmati rice, cooked","grams":110},{"food":"Broccoli","grams":85},{"food":"Edamame beans, frozen","grams":70},{"food":"Soy sauce","grams":15}]}]}]}$$::jsonb),
